def obraz():
    """Zwraca zdjecie gotowe do uzycia albo None, gdy sie nie uda."""
    try:
        from PIL import Image
        return Image.open(io.BytesIO(base64.b64decode(DANE))).convert("RGB")
    except Exception:
        return None


